package com.varabyte.kobweb.icons.codegen

import java.io.File

/**
 * A comment line that starts each file icons-codegen writes, marking it as autogenerated.
 *
 * It's meant to be the file's first line, where readers and tools look for a generated-code marker.
 */
internal sealed class AutogeneratedNotice(val text: String) {
    /** Starts each Kotlin file of bindings, naming the [iconsFile] they were generated from. */
    class Bindings(iconsFile: File) :
        AutogeneratedNotice("// THIS FILE IS AUTOGENERATED from `${iconsFile.name}`. Do not edit it by hand.")

    /**
     * Starts each icons file written by [IconSet.fetch], naming the upstream [source] its data came from, e.g.
     * "FortAwesome/Font-Awesome @ 6.5.2".
     */
    class IconsFile(source: String) :
        AutogeneratedNotice("# THIS FILE IS AUTOGENERATED from $source. Fetch it again instead of editing it by hand.")
}
